// Read-only scan: lists every block in build.nbt whose id is not in palette.json (args: file, palette), with coordinates.
import { load } from "/Volumes/ext1/swe/repos/minecraft-design/tools/src/build.mjs";
import { readFileSync } from "node:fs";
const [file, palFile] = process.argv.slice(2);
const pal = JSON.parse(readFileSync(palFile, "utf8"));
const ok = new Set(Object.values(pal.roles).flat().concat(pal.objects ?? []).map((s) => `minecraft:${s}`));
const g = load(file);
const [W, H, D] = g.size ?? [g.width, g.height, g.depth];
const hits = {};
for (let x = 0; x < 42; x++) for (let y = 0; y < 16; y++) for (let z = 0; z < 38; z++) {
  const b = g.blockAt(x, y, z);
  if (b === "minecraft:air" || ok.has(b)) continue;
  (hits[b] ??= []).push(`${x},${y},${z}`);
}
for (const [b, cells] of Object.entries(hits)) console.log(b, cells.length, cells.slice(0, 40).join(" "));
EOF
